mapper.select:
SELECT d.outbound_id,d.order_id,d.warehouse_id,l.order_line_id,l.product_id,l.quantity,d.posted_at FROM inventory_outbound_documents d JOIN inventory_outbound_lines l ON l.outbound_id=d.outbound_id WHERE d.merchant_id=#{merchantId} AND d.order_id IN
#{orderId}
ORDER BY d.order_id,d.posted_at,d.outbound_id,l.order_line_id

SELECT event_id,payload FROM inventory_outbound_event_outbox
WHERE published_at IS NULL AND next_attempt_at<=CURRENT_TIMESTAMP(6)
ORDER BY next_attempt_at,event_id LIMIT #{limit}
